-- Milestone 3 / study plans: one stored plan per student, generated by the server from the exam date,
-- the student's study time and what the question bank contains. Saving a plan again replaces it.
-- How much of the plan is done is derived from the student's answers, so nothing here records progress.
--
-- The plan's weeks are stored as one jsonb document because they are only ever read and replaced
-- whole; the server validates the document when it reads it back.

CREATE TABLE public.study_plans (
  user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  exam_type public.exam_type NOT NULL,
  exam_date date NOT NULL,
  starts_on date NOT NULL,
  daily_minutes integer NOT NULL CHECK (daily_minutes BETWEEN 10 AND 240),
  days_per_week integer NOT NULL CHECK (days_per_week BETWEEN 1 AND 7),
  target_score integer NOT NULL CHECK (target_score BETWEEN 50 AND 100),
  questions_per_day integer NOT NULL CHECK (questions_per_day >= 1),
  plan jsonb NOT NULL CHECK (jsonb_typeof(plan) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (exam_date > starts_on)
);

ALTER TABLE public.study_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY "students read own study plan" ON public.study_plans
  FOR SELECT TO authenticated USING (user_id = auth.uid());
REVOKE ALL ON public.study_plans FROM anon, authenticated;
GRANT SELECT ON public.study_plans TO authenticated;
GRANT ALL ON public.study_plans TO service_role;
